package com.zgmemory.android;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import android.media.MediaPlayer;import org.json.*;import java.net.*;import java.io.*;import java.util.*;
public class MainActivity extends Activity {
 EditText searchBox; LinearLayout listLayout; TextView status,nowPlaying; Button playPause; MediaPlayer player; ArrayList<JSONObject> songs=new ArrayList<>(); JSONObject currentSong; String supabaseUrl="",publishableKey=""; final String PREFS="zg_config";
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(20,18,28));getWindow().setNavigationBarColor(Color.BLACK);android.content.SharedPreferences p=getSharedPreferences(PREFS,0);supabaseUrl=p.getString("url","");publishableKey=p.getString("key","");buildUI();if(supabaseUrl.isEmpty()||publishableKey.isEmpty())showConfig();else loadSongs("");}
 void buildUI(){ScrollView sc=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(18),dp(18),dp(18));root.setBackgroundColor(Color.rgb(18,16,24));sc.addView(root);TextView brand=new TextView(this);brand.setText("ZG MEMORY");brand.setTextColor(-1);brand.setTextSize(26);brand.setTypeface(null,1);root.addView(brand);TextView sub=new TextView(this);sub.setText("Zubeen Garg • Music Library");sub.setTextColor(Color.LTGRAY);root.addView(sub);Button settings=new Button(this);settings.setText("Supabase Settings");settings.setOnClickListener(v->showConfig());root.addView(settings);searchBox=new EditText(this);searchBox.setSingleLine(true);searchBox.setHint("Search song, album, year...");searchBox.setTextColor(-1);root.addView(searchBox);Button search=new Button(this);search.setText("Search Songs");search.setOnClickListener(v->{((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(searchBox.getWindowToken(),0);loadSongs(searchBox.getText().toString().trim());});root.addView(search);status=new TextView(this);status.setTextColor(Color.LTGRAY);root.addView(status);listLayout=new LinearLayout(this);listLayout.setOrientation(1);root.addView(listLayout);nowPlaying=new TextView(this);nowPlaying.setText("Nothing playing");nowPlaying.setTextColor(-1);root.addView(nowPlaying);LinearLayout controls=new LinearLayout(this);Button prev=new Button(this);prev.setText("Previous");prev.setOnClickListener(v->playAt(Math.max(0,indexOfCurrent()-1)));playPause=new Button(this);playPause.setText("Play / Pause");playPause.setOnClickListener(v->togglePlayback());Button next=new Button(this);next.setText("Next");next.setOnClickListener(v->playAt(Math.min(songs.size()-1,indexOfCurrent()+1)));controls.addView(prev,new LinearLayout.LayoutParams(0,-2,1));controls.addView(playPause,new LinearLayout.LayoutParams(0,-2,1));controls.addView(next,new LinearLayout.LayoutParams(0,-2,1));root.addView(controls);setContentView(sc);}
 void showConfig(){LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(dp(20),dp(8),dp(20),0);EditText u=new EditText(this);u.setSingleLine(true);u.setHint("Supabase Project URL");u.setText(supabaseUrl);EditText k=new EditText(this);k.setSingleLine(true);k.setHint("Publishable / anon key ONLY");k.setText(publishableKey);form.addView(u);form.addView(k);new AlertDialog.Builder(this).setTitle("Connect ZG Memory").setMessage("Never enter service_role or secret keys. Use the project URL and publishable/anon key.").setView(form).setPositiveButton("Save & Connect",(d,w)->{supabaseUrl=u.getText().toString().trim().replaceAll("/+$","");publishableKey=k.getText().toString().trim();getSharedPreferences(PREFS,0).edit().putString("url",supabaseUrl).putString("key",publishableKey).apply();loadSongs("");}).setNegativeButton("Cancel",null).show();}
 void loadSongs(String q){if(supabaseUrl.isEmpty()||publishableKey.isEmpty()){status.setText("Add Supabase settings first.");return;}status.setText("Loading songs…");listLayout.removeAllViews();new Thread(()->{HttpURLConnection c=null;try{String url=supabaseUrl+"/rest/v1/songs?select=*&order=sort_order.asc";if(!q.isEmpty())url+="&or=("+enc("title.ilike.*"+q+"*")+","+enc("album.ilike.*"+q+"*")+","+enc("artist.ilike.*"+q+"*")+")";c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod("GET");c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("apikey",publishableKey);c.setRequestProperty("Authorization","Bearer "+publishableKey);int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();String body=readAll(in);if(code<200||code>=300)throw new Exception("HTTP "+code+": "+body);JSONArray a=new JSONArray(body);ArrayList<JSONObject> got=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject s=a.getJSONObject(i);if(s.optString("artist","").toLowerCase(Locale.ROOT).contains("zubeen garg"))got.add(s);}runOnUiThread(()->{songs=got;status.setText(got.size()+" Zubeen Garg songs found");if(got.isEmpty())msg("No songs found. Check RLS and artist values.");for(JSONObject s:got)addRow(s);});}catch(Exception e){String m=e.getMessage()==null?"Unknown error":e.getMessage();runOnUiThread(()->status.setText("Load failed: "+m));}finally{if(c!=null)c.disconnect();}}).start();}
 void addRow(JSONObject s){LinearLayout r=new LinearLayout(this);r.setOrientation(1);r.setPadding(dp(8),dp(8),dp(8),dp(8));TextView t=new TextView(this);t.setText(s.optString("title","Untitled"));t.setTextColor(-1);t.setTextSize(16);t.setTypeface(null,1);r.addView(t);TextView m=new TextView(this);m.setText(s.optString("album","Album unknown")+" • "+s.optString("year",""));m.setTextColor(Color.LTGRAY);r.addView(m);Button p=new Button(this);p.setText("▶ Play");p.setOnClickListener(v->playSong(s));r.addView(p);listLayout.addView(r);}
 void msg(String s){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.LTGRAY);listLayout.addView(t);}
 String audioUrl(JSONObject s)throws Exception{String p=s.optString("audio_path","");if(p.startsWith("http://")||p.startsWith("https://"))return p;if(p.isEmpty()||p.equals("null"))throw new Exception("Missing audio_path");return supabaseUrl+"/storage/v1/object/public/music-audio/"+pathEncode(p);}
 void playSong(JSONObject s){try{if(player!=null){player.release();player=null;}currentSong=s;String u=audioUrl(s);nowPlaying.setText("Loading: "+s.optString("title",""));player=new MediaPlayer();player.setDataSource(u);player.setOnPreparedListener(mp->{mp.start();nowPlaying.setText("Now playing: "+s.optString("title",""));playPause.setText("Pause");});player.setOnCompletionListener(mp->playPause.setText("Play / Pause"));player.setOnErrorListener((mp,w,e)->{nowPlaying.setText("Playback error: check audio_path and bucket object path.");return true;});player.prepareAsync();}catch(Exception e){nowPlaying.setText("Cannot play: "+e.getMessage());}}
 void togglePlayback(){if(player==null){playAt(0);return;}if(player.isPlaying()){player.pause();playPause.setText("Play");}else{player.start();playPause.setText("Pause");}}
 int indexOfCurrent(){if(currentSong==null)return 0;for(int i=0;i<songs.size();i++)if(songs.get(i).optString("id","").equals(currentSong.optString("id","")))return i;return 0;}
 void playAt(int i){if(i>=0&&i<songs.size())playSong(songs.get(i));}
 String readAll(InputStream in)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream();byte[]b=new byte[8192];int n;while((n=in.read(b))!=-1)o.write(b,0,n);return o.toString("UTF-8");}
 String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 String pathEncode(String p)throws Exception{String[]a=p.split("/");StringBuilder b=new StringBuilder();for(int i=0;i<a.length;i++){if(i>0)b.append('/');b.append(enc(a[i]).replace("+","%20"));}return b.toString();}
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 protected void onDestroy(){if(player!=null)player.release();super.onDestroy();}
}
